const crypto = require('crypto');
const event = $input.first().json;
const message = event.message || {};
const configuredChat = String($env.INSIGHT_TELEGRAM_CEO_CHAT_ID || '').trim();
const incomingChat = String(message.chat?.id ?? '');
if (!configuredChat || incomingChat !== configuredChat) return [];
const text = String(message.text || '').trim();
const command = text.split(/\s+/)[0].split('@')[0].toLowerCase();
const commands = { '/tasks': 'current_tasks', '/overdue': 'overdue_tasks', '/attendance': 'attendance' };
const help = 'أوامر إنسايت بروجكتس:\n/tasks - تقرير المهام الحالية\n/overdue - تقرير المهام المتأخرة\n/attendance - تقرير حضور المتدربين بالأسماء\n/last - إعادة إرسال آخر إجابة ذكاء اصطناعي بدون استهلاك جديد\n/help - عرض المساعدة\n\nأو أرسل سؤالاً تنفيذياً بالعربية أو الإنجليزية عن مخاطر المشاريع والمهام والمواعيد والتعطل والتقدم والاعتمادات.';
const isLatest = command === '/last';
if (!text || command === '/help' || (command.startsWith('/') && !commands[command] && !isLatest)) return [{ json: { kind: 'help', text: help } }];
const secret = String($env.INSIGHT_N8N_SIGNING_SECRET || '');
const baseUrl = String($env.INSIGHT_APP_BASE_URL || '').replace(/\/$/, '');
if (!secret || !baseUrl) throw new Error('Missing Insight integration configuration');
const kind = commands[command] ? 'report' : 'assistant';
const path = isLatest ? '/integrations/n8n/telegram/assistant/latest/' : kind === 'report' ? '/integrations/n8n/telegram/reports/start/' : '/integrations/n8n/telegram/assistant/start/';
const payload = isLatest ? { chat_id: configuredChat } : kind === 'report' ? { chat_id: configuredChat, report_type: commands[command], window_days: 30 } : { chat_id: configuredChat, message_id: String(message.message_id || ''), question: text };
const body = JSON.stringify(payload);
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomBytes(24).toString('base64url');
const bodyHash = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, bodyHash].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
return [{ json: { kind, url: baseUrl + path, body, timestamp, nonce, signature } }];

const root = $input.first().json;
const queue = [root];
let normalized = null;
for (let index = 0; index < queue.length && index < 16; index += 1) {
  let candidate = queue[index];
  if (typeof candidate === 'string') {
    try { candidate = JSON.parse(candidate); } catch { continue; }
  }
  if (!candidate || typeof candidate !== 'object') continue;
  if (candidate.status || candidate.request_id || candidate.message || candidate.message_ar) { normalized = candidate; break; }
  for (const key of ['body', 'data', 'response', 'json']) {
    if (candidate[key] !== undefined) queue.push(candidate[key]);
  }
}
if (!normalized) throw new Error('Invalid Insight response');
return [{ json: normalized }];

const crypto = require('crypto');
const current = $input.first().json;
const started = $('Normalize Start Response').first().json;
const candidates = [started, current, current.body];
let response = started;
for (const candidate of candidates) {
  if (candidate && typeof candidate === 'object' && (candidate.request_id || candidate.id)) { response = candidate; break; }
}
const requestId = String(response.request_id || response.id || '');
const kind = response.kind === 'assistant' || started.kind === 'assistant' ? 'assistant' : 'report';
const configuredChat = String($env.INSIGHT_TELEGRAM_CEO_CHAT_ID || '').trim();
const secret = String($env.INSIGHT_N8N_SIGNING_SECRET || '');
const baseUrl = String($env.INSIGHT_APP_BASE_URL || '').replace(/\/$/, '');
if (!requestId || !configuredChat || !secret || !baseUrl) throw new Error('Missing request status configuration');
const path = kind === 'assistant' ? '/integrations/n8n/telegram/assistant/status/' : '/integrations/n8n/telegram/reports/status/';
const body = JSON.stringify({ chat_id: configuredChat, request_id: requestId });
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomBytes(24).toString('base64url');
const bodyHash = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, bodyHash].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
return [{ json: { kind, url: baseUrl + path, body, timestamp, nonce, signature } }];

const response = $input.first().json;
const baseUrl = String($env.INSIGHT_APP_BASE_URL || '').replace(/\/$/, '');
const downloadPath = String(response.download_path || '');
const allowedPath = /^\/integrations\/n8n\/telegram\/reports\/[0-9a-f-]{36}\/download\/\?token=[A-Za-z0-9._~%+-]+$/;
if (!/^https?:\/\/[^/]+$/.test(baseUrl) || !allowedPath.test(downloadPath)) throw new Error('Invalid report download target');
return [{ json: { ...response, download_url: baseUrl + downloadPath } }];

const crypto = require('crypto');
const configuredChat = String($env.INSIGHT_TELEGRAM_CEO_CHAT_ID || '').trim();
const secret = String($env.INSIGHT_N8N_SIGNING_SECRET || '');
const baseUrl = String($env.INSIGHT_APP_BASE_URL || '').replace(/\/$/, '');
if (!configuredChat || !secret || !baseUrl) throw new Error('Missing critical alert configuration');
const path = '/integrations/n8n/telegram/alerts/claim/';
const body = JSON.stringify({ chat_id: configuredChat });
const timestamp = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomBytes(24).toString('base64url');
const bodyHash = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const canonical = [timestamp, nonce, 'POST', path, bodyHash].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
return [{ json: { url: baseUrl + path, body, timestamp, nonce, signature } }];

const crypto = require('crypto');
const response = $input.first().json;
const alerts = Array.isArray(response.alerts) ? response.alerts : [];
if (!alerts.length) return [];
const configuredChat = String($env.INSIGHT_TELEGRAM_CEO_CHAT_ID || '').trim();
const secret = String($env.INSIGHT_N8N_SIGNING_SECRET || '');
const baseUrl = String($env.INSIGHT_APP_BASE_URL || '').replace(/\/$/, '');
if (!response.lease_token || !configuredChat || !secret || !baseUrl) throw new Error('Invalid critical alert claim response');
const path = '/integrations/n8n/telegram/alerts/acknowledge/';
return alerts.map((alert) => {
  const body = JSON.stringify({ chat_id: configuredChat, lease_token: String(response.lease_token), alert_ids: [String(alert.alert_id)] });
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomBytes(24).toString('base64url');
  const bodyHash = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
  const canonical = [timestamp, nonce, 'POST', path, bodyHash].join('\n');
  const signature = crypto.createHmac('sha256', secret).update(canonical, 'utf8').digest('hex');
  return { json: { message_ar: String(alert.message_ar), url: baseUrl + path, body, timestamp, nonce, signature } };
});
